<?php
declare(strict_types=1);
$states = ['queued' => 'În așteptare', 'claimed' => 'Preluată', 'dispatched' => 'Trimisă echipamentului', 'confirmed' => 'Confirmată de echipament', 'failed' => 'Nereușită', 'uncertain' => 'Necesită verificare', 'cancelled' => 'Anulată'];
$activeDevices = array_values(array_filter($devices, static fn($device) => $device['revoked_at'] === null));
?>
<div class="container page-space marketplace-page"><div class="eyebrow">ETICHETE ȘI ECHIPAMENTE</div><h1 class="page-title">De la lot la ambalaj.</h1><p class="lead">Coduri QR GS1 Digital Link, serii distincte și istoric pentru fiecare comandă de tipărire.</p><p><a href="/manage">← Spațiul meu</a> · <a href="/marketplace">Găsește un conector</a> · <a href="/api/docs/guides/marketplace">Conectarea unui echipament</a></p>
<?php if ($secret !== null): ?><section class="panel"><h2>Accesul agentului</h2><p>Salvează credentialul în configurația privată a agentului. Este afișat o singură dată și permite numai preluarea comenzilor echipamentului.</p><input class="form-control" readonly value="<?= e($secret) ?>" aria-label="Credentialul agentului" autocomplete="off"></section><?php endif ?>
<div class="row g-4"><div class="col-lg-6"><section class="panel h-100"><h2>Echipamente</h2><?php foreach ($devices as $device): ?><article class="marketplace-release"><h3><?= e($device['name']) ?></h3><p><?= e(strtoupper($device['format'])) ?> · <?= $device['revoked_at'] ? 'Deconectat' : 'Acces activ' ?></p><?php if (!$device['revoked_at'] && $p['role'] === 'owner'): ?><form method="post"><?= csrf() ?><input type="hidden" name="id" value="<?= e($device['id']) ?>"><button class="btn btn-outline-primary btn-sm" name="action" value="revoke">Deconectează agentul</button></form><?php endif ?><?php if($p['role']==='owner'):?><details class="mt-3"><summary>Înlocuiește accesul agentului</summary><form method="post" class="form-stack mt-3"><?=csrf()?><input type="hidden" name="id" value="<?=e($device['id'])?>"><label>Confirmă parola contului<input type="password" name="current_password" class="form-control" autocomplete="current-password" maxlength="200" required></label><button class="btn btn-outline-primary btn-sm" name="action" value="rotate">Generează alt credential</button></form></details><?php endif ?></article><?php endforeach ?><?php if (!$devices): ?><p>Nu ai conectat echipamente.</p><?php endif ?>
<?php if ($p['role'] === 'owner'): ?><form method="post" class="form-stack mt-4"><?= csrf() ?><input type="hidden" name="action" value="device"><label>Nume echipament<input name="name" class="form-control" maxlength="120" required></label><label>Format pentru agent<select name="format" class="form-select"><option value="json">JSON — adaptor propriu</option><option value="zpl">ZPL — echipament compatibil</option></select></label><label>Confirmă parola contului<input name="current_password" type="password" autocomplete="current-password" class="form-control" maxlength="200" required></label><button class="btn btn-primary">Adaugă echipamentul</button></form><?php endif ?></section></div>
<div class="col-lg-6"><section class="panel h-100"><h2>Comandă nouă</h2><p>Fiecare ambalaj primește o serie unică. GTIN-ul, lotul și datele aplicabile sunt preluate din informațiile aprobate.</p><?php if ($activeDevices && $batches && in_array($p['role'], ['owner', 'editor', 'quality'], true)): ?><form method="post" class="form-stack"><?= csrf() ?><input type="hidden" name="action" value="job"><input type="hidden" name="request_key" value="<?= e(bin2hex(random_bytes(16))) ?>"><label>Echipament<select name="device_id" class="form-select" required><?php foreach ($devices as $device): ?><?php if (!$device['revoked_at']): ?><option value="<?= e($device['id']) ?>"><?= e($device['name']) ?></option><?php endif ?><?php endforeach ?></select></label><label>Produs și lot<select name="batch_id" class="form-select" required><?php foreach ($batches as $batch): ?><option value="<?= e($batch['id']) ?>"><?= e($batch['name'] . ' · ' . $batch['lot_code']) ?></option><?php endforeach ?></select></label><label>Număr de ambalaje<input type="number" name="quantity" min="1" max="500" value="1" class="form-control" required></label><button class="btn btn-primary">Pregătește etichetele</button></form><?php else: ?><p>Adaugă un echipament și publică un lot cu GTIN verificat pentru a pregăti etichete.</p><?php endif ?></section></div></div>
<section class="panel mt-4"><h2>Comenzi</h2><p class="small muted">„Trimisă echipamentului” confirmă transferul datelor. Tipărirea fizică este confirmată separat, dacă echipamentul oferă acest răspuns.</p><?php if (!$jobs): ?><p>Nu există comenzi de tipărire.</p><?php endif ?><?php foreach ($jobs as $entry): ?><article class="marketplace-release"><h3><a href="/manage/printing?job=<?= e($entry['id']) ?>"><?= e($entry['quantity']) ?> ambalaje · <?= e($states[$entry['state']] ?? $entry['state']) ?></a></h3><p><?= e(ro_time($entry['created_at'])) ?> · <?= e(strtoupper($entry['format'])) ?></p></article><?php endforeach ?></section>
