<?php foreach ($job['events'] as $event): ?><p><strong><?= e($states[$event['state']] ?? $event['state']) ?></strong> · <?= e($event['evidence']) ?> · <?= e(ro_time($event['created_at'])) ?></p><?php endforeach ?>
<?php if ($job['state'] === 'queued' && in_array($p['role'], ['owner', 'editor', 'quality'], true)): ?><form method="post" class="form-stack"><?= csrf() ?><input type="hidden" name="id" value="<?= e($job['id']) ?>"><label>Motivul anulării<input name="reason" class="form-control" maxlength="1000" required></label><button name="action" value="cancel" class="btn btn-outline-primary">Anulează comanda</button></form><?php elseif (in_array($job['state'], ['dispatched', 'confirmed', 'failed', 'uncertain', 'cancelled'], true) && $activeDevices && in_array($p['role'], ['owner', 'quality'], true)): ?><form method="post" class="form-stack"><?= csrf() ?><input type="hidden" name="id" value="<?= e($job['id']) ?>"><label>Echipament<select name="device_id" class="form-select" required><?php foreach($activeDevices as $target):?><option value="<?=e($target['id'])?>" <?=$target['id']===$job['device_id']?'selected':''?>><?=e($target['name'])?></option><?php endforeach?></select></label><label>Motivul retipăririi<input name="reason" class="form-control" maxlength="1000" required></label><label class="check-label"><input type="checkbox" name="same_serials_confirmed" required> Înlocuiesc etichete folosind aceleași serii; nu creez ambalaje noi.</label><button name="action" value="reprint" class="btn btn-outline-primary">Creează comanda de retipărire</button></form><?php endif ?></section><?php endif ?>
</div>
